const taskKeys = {
  all: ["tasks"] as const,
  list: (filters) => ["tasks", "list", filters] as const,
  detail: (id) => ["tasks", "detail", id] as const,
};

useQuery({
  queryKey: taskKeys.list(filters),
  queryFn: () => getTasks(filters),
  staleTime: 30_000,
});

const mutation = useMutation({
  mutationFn: createTask,
  onSuccess: () => queryClient.invalidateQueries({ queryKey: taskKeys.all }),
});

onMutate: async (next) => {
  await queryClient.cancelQueries({ queryKey: taskKeys.all });
  const previous = queryClient.getQueryData(taskKeys.all);
  queryClient.setQueryData(taskKeys.all, optimistic(next));
  return { previous };
},
onError: (_e,_v,ctx) => queryClient.setQueryData(taskKeys.all, ctx?.previous)
